def latestTime(s: str) -> str:
    s_list = list(s)

    # Handle Hour (HH)
    # First digit of hour
    if s_list[0] == '?':
        # If the second digit is '0' or '1', the first digit can be '1'.
        # If the second digit is '?', we can set first to '1' and second to '1'.
        # If the second digit is '2'-'9', the first digit must be '0'.
        if s_list[1] == '?' or s_list[1] <= '1':
            s_list[0] = '1'
        else:
            s_list[0] = '0'

    # Second digit of hour
    if s_list[1] == '?':
        # If first digit is '0', max second digit is '9'.
        # If first digit is '1', max second digit is '1'.
        if s_list[0] == '0':
            s_list[1] = '9'
        else:
            s_list[1] = '1'

    # Handle Minutes (MM)
    # First digit of minute (0-5)
    if s_list[3] == '?':
        s_list[3] = '5'

    # Second digit of minute (0-9)
    if s_list[4] == '?':
        s_list[4] = '9'

    return "".join(s_list)
```

