import sys

def solve():
    # Read all input at once for efficiency
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    cuboids = []
    idx = 1
    for i in range(N):
        x1 = int(input_data[idx])
        y1 = int(input_data[idx+1])
        z1 = int(input_data[idx+2])
        x2 = int(input_data[idx+3])
        y2 = int(input_data[idx+4])
        z2 = int(input_data[idx+5])
        cuboids.append((x1, y1, z1, x2, y2, z2))
        idx += 6

    # The constraints on coordinates are very small (0 to 100).
    # We can use a 3D grid to mark which cuboid occupies which unit cell.
    # Since we need to find shared faces, we can check the boundaries.
    # A unit cell (x, y, z) represents the space [x, x+1) x [y, y+1) x [z, z+1).
    grid = [[[-1 for _ in range(100)] for _ in range(100)] for _ in range(100)]

    for i in range(N):
        x1, y1, z1, x2, y2, z2 = cuboids[i]
        for x in range(x1, x2):
            for y in range(y1, y2):
                for z in range(z1, z2):
                    grid[x][y][z] = i

    adj = [set() for _ in range(N)]

    # Check faces in X direction
    for x in range(99):
        for y in range(100):
            for z in range(100):
                id1 = grid[x][y][z]
                id2 = grid[x+1][y][z]
                if id1 != -1 and id2 != -1 and id1 != id2:
                    adj[id1].add(id2)
                    adj[id2].add(id1)

    # Check faces in Y direction
    for x in range(100):
        for y in range(99):
            for z in range(100):
                id1 = grid[x][y][z]
                id2 = grid[x][y+1][z]
                if id1 != -1 and id2 != -1 and id1 != id2:
                    adj[id1].add(id2)
                    adj[id2].add(id1)

    # Check faces in Z direction
    for x in range(100):
        for y in range(100):
            for z in range(99):
                id1 = grid[x][y][z]
                id2 = grid[x][y][z+1]
                if id1 != -1 and id2 != -1 and id1 != id2:
                    adj[id1].add(id2)
                    adj[id2].add(id1)

    # Print the number of unique neighbors for each cuboid
    output = []
    for i in range(N):
        output.append(str(len(adj[i])))

    sys.stdout.write('\n'.join(output) + '\n')

if __name__ == "__main__":
    solve()
```

```python
def specialLettersCount(word: str) -> int:
    # Create sets to track seen lowercase and uppercase characters
    lower_seen = set()
    upper_seen = set()

    for char in word:
        if char.islower():
            lower_seen.add(char)
        elif char.isupper():
            upper_seen.add(char.lower())

    # The number of special letters is the size of the intersection of both sets
    return len(lower_seen.intersection(upper_seen))
```

