import sys

def solve():
    # Read H and W
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    H = int(input_data[0])
    W = int(input_data[1])
    grid = input_data[2:]

    MOD = 998244353

    # Find all green cells
    green_cells = []
    red_cells = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '#':
                green_cells.append((r, c))
            else:
                red_cells.append((r, c))

    # Disjoint Set Union to find initial connected components
    parent = {}
    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    for r, c in green_cells:
        parent[(r, c)] = (r, c)

    initial_components = len(green_cells)
    for r, c in green_cells:
        for dr, dc in [(0, 1), (1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == '#':
                if union((r, c), (nr, nc)):
                    initial_components -= 1

    # For each red cell, calculate the change in components if it becomes green
    # New components = initial_components + 1 - (number of distinct components it connects)
    total_sum = 0
    for r, c in red_cells:
        neighbors = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == '#':
                neighbors.append(find((nr, nc)))

        distinct_components = len(set(neighbors))
        total_sum = (total_sum + initial_components + 1 - distinct_components) % MOD

    # Expected value = total_sum / number_of_red_cells
    num_red = len(red_cells)
    # Modular inverse of num_red
    inv_red = pow(num_red, MOD - 2, MOD)
    print((total_sum * inv_red) % MOD)

if __name__ == "__main__":
    # Increase recursion depth for deep DSU trees
    sys.setrecursionlimit(2000000)
    solve()
```

