import sys

def solve():
    # Read N and M
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    # Initialize distance matrix for Floyd-Warshall
    INF = float('inf')
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    idx = 2
    for _ in range(M):
        u = int(input_data[idx]) - 1
        v = int(input_data[idx+1]) - 1
        w = int(input_data[idx+2])
        dist[u][v] = min(dist[u][v], w)
        idx += 3

    # Floyd-Warshall to find all-pairs shortest paths
    for k in range(N):
        for i in range(N):
            if dist[i][k] == INF: continue
            for j in range(N):
                if dist[k][j] < INF:
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    # DP state: dp[mask][last_vertex]
    # mask: bitmask of visited vertices
    # last_vertex: the current vertex the walk is at
    dp = [[INF] * N for _ in range(1 << N)]

    # Base case: start at any vertex i
    for i in range(N):
        dp[1 << i][i] = 0

    # Iterate through all masks
    for mask in range(1, 1 << N):
        for u in range(N):
            if dp[mask][u] == INF:
                continue

            # Try moving to any vertex v not yet visited in the mask
            # Note: We can move to any vertex v, but we only care about 
            # updating the mask when v is not in it.
            # However, the shortest path dist[u][v] already accounts for 
            # visiting intermediate vertices.
            for v in range(N):
                if not (mask & (1 << v)):
                    if dist[u][v] != INF:
                        new_mask = mask | (1 << v)
                        if dp[new_mask][v] > dp[mask][u] + dist[u][v]:
                            dp[new_mask][v] = dp[mask][u] + dist[u][v]

    # The answer is the minimum value in dp[(1 << N) - 1]
    ans = min(dp[(1 << N) - 1])

    if ans == INF:
        print("No")
    else:
        print(ans)

if __name__ == "__main__":
    solve()

```

```python
def maxEnergy(energy, k):
    n = len(energy)
    # dp[i] will store the maximum energy gained starting from index i
    # We iterate backwards because the value at i depends on the value at i + k
    dp = [0] * n

    for i in range(n - 1, -1, -1):
        # The energy gained at index i is the current magician's energy
        # plus the energy from the magician at (i + k), if they exist.
        if i + k < n:
            dp[i] = energy[i] + dp[i + k]
        else:
            dp[i] = energy[i]

    return max(dp)
```

