def sum_imbalance_numbers(nums):
    n = len(nums)
    total = 0
    for i in range(n):
        seen = set()
        for j in range(i, n):
            seen.add(nums[j])
            s = sorted(seen)
            imb = 0
            for k in range(len(s) - 1):
                if s[k+1] - s[k] > 1:
                    imb += 1
