def furthest_point(moves: str) -> int:
    """
    Calculates the maximum distance from the origin after n moves.
    To maximize distance, we want to move as far as possible in one direction.
    We can either try to go as far left as possible or as far right as possible.
    """
    # To go as far left as possible:
    # Treat '_' as 'L' and 'L' as 'L'. 'R' must remain 'R'.
    left_dist = 0
    for char in moves:
        if char == 'L' or char == '_':
            left_dist -= 1
        else:
            left_dist += 1

    # To go as far right as possible:
    # Treat '_' as 'R' and 'R' as 'R'. 'L' must remain 'L'.
    right_dist = 0
    for char in moves:
        if char == 'R' or char == '_':
            right_dist += 1
        else:
            right_dist -= 1

    # The distance is the absolute value of the final position.
    return max(abs(left_dist), abs(right_dist))
```

