import sys
from itertools import permutations

def solve():
    # Read H and W
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])

    A = []
    idx = 2
    for i in range(H):
        A.append([int(x) for x in input_data[idx : idx + W]])
        idx += W

    B = []
    for i in range(H):
        B.append([int(x) for x in input_data[idx : idx + W]])
        idx += W

    def get_inversions(p):
        inv = 0
        for i in range(len(p)):
            for j in range(i + 1, len(p)):
                if p[i] > p[j]:
                    inv += 1
        return inv

    min_ops = float('inf')
    found = False

    # The operations are swapping adjacent rows and adjacent columns.
    # This is equivalent to finding a permutation of rows (P) and a permutation of columns (Q)
    # such that A[P[i]][Q[j]] == B[i][j].
    # The total number of operations is the number of inversions in P plus the number of inversions in Q.

    # Since H and W are small (up to 5), we can iterate through all permutations.
    row_perms = list(permutations(range(H)))
    col_perms = list(permutations(range(W)))

    for p in row_perms:
        # p[i] is the index of the row in A that moves to position i in B
        # However, the problem asks for the number of swaps to transform A to B.
        # If we define p such that A's row p[i] becomes B's row i, 
        # then the number of swaps is the inversion count of p.

        for q in col_perms:
            # q[j] is the index of the column in A that moves to position j in B
            possible = True
            for i in range(H):
                for j in range(W):
                    if A[p[i]][q[j]] != B[i][j]:
                        possible = False
                        break
                if not possible:
                    break

            if possible:
                found = True
                ops = get_inversions(p) + get_inversions(q)
                if ops < min_ops:
                    min_ops = ops

    if not found:
        print("-1")
    else:
        print(min_ops)

if __name__ == "__main__":
    solve()

