def min_operations_to_make_median_k(nums, k):
    nums.sort()
    n = len(nums)
    median_index = n // 2
    median = nums[median_index]

    if median == k:
        return 0
    elif median < k:
        ops = 0
        for i in range(median_index, n):
            if nums[i] < k:
                ops += k - nums[i]
            else:
                break
        return ops
    else:
        ops = 0
        for i in range(median_index, -1, -1):
            if nums[i] > k:
                ops += nums[i] - k
            else:
                break
        return ops
