import sys
from collections import deque

def solve():
    # Read H, W, T
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    H = int(input_data[0])
    W = int(input_data[1])
    T = int(input_data[2])
    grid = input_data[3:]

    start_pos = None
    goal_pos = None
    candies = []

    for r in range(H):
        for c in range(W):
            char = grid[r][c]
            if char == 'S':
                start_pos = (r, c)
            elif char == 'G':
                goal_pos = (r, c)
            elif char == 'o':
                candies.append((r, c))

    # All points of interest: Start, Candies, Goal
    nodes = [start_pos] + candies + [goal_pos]
    num_nodes = len(nodes)
    num_candies = len(candies)

    # Distance matrix between all points of interest
    dist_matrix = [[float('inf')] * num_nodes for _ in range(num_nodes)]

    def bfs(start_idx):
        sr, sc = nodes[start_idx]
        dists = [[-1] * W for _ in range(H)]
        dists[sr][sc] = 0
        queue = deque([(sr, sc)])

        while queue:
            r, c = queue.popleft()
            d = dists[r][c]
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#' and dists[nr][nc] == -1:
                    dists[nr][nc] = d + 1
                    queue.append((nr, nc))

        for i in range(num_nodes):
            tr, tc = nodes[i]
            if dists[tr][tc] != -1:
                dist_matrix[start_idx][i] = dists[tr][tc]

    for i in range(num_nodes):
        bfs(i)

    # DP state: dp[mask][i] = min distance to visit candies in mask, ending at node i
    # mask represents the set of candies visited.
    # i is the index in the 'nodes' list (0 to num_candies)
    # Goal is handled separately at the end.

    # We only need DP for the start and the candies.
    # dp[mask][i] where i is index of candy (0 to num_candies-1)
    dp = [[float('inf')] * num_candies for _ in range(1 << num_candies)]

    # Initialize DP with distances from start to each candy
    for i in range(num_candies):
        dp[1 << i][i] = dist_matrix[0][i + 1]

    # Fill DP
    for mask in range(1, 1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i] == float('inf'):
                continue
            # Try moving to another candy not in mask
            for next_candy in range(num_candies):
                if not (mask & (1 << next_candy)):
                    new_mask = mask | (1 << next_candy)
                    new_dist = dp[mask][i] + dist_matrix[i + 1][next_candy + 1]
                    if new_dist < dp[new_mask][next_candy]:
                        dp[new_mask][next_candy] = new_dist

    # Check if goal is reachable from start directly
    max_candies = -1
    if dist_matrix[0][num_nodes - 1] <= T:
        max_candies = 0

    # Check all combinations of candies and then move to goal
    for mask in range(1, 1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i] == float('inf'):
                continue
            # Distance from last candy to goal
            total_dist = dp[mask][i] + dist_matrix[i + 1][num_nodes - 1]
            if total_dist <= T:
                # Count set bits in mask
                count = bin(mask).count('1')
                if count > max_candies:
                    max_candies = count

    print(max_candies)

if __name__ == "__main__":
    solve()
