def max_element_sum(nums):
    """
    A set of numbers is complete if the product of every pair is a perfect square.
    Two numbers a and b satisfy this if their square-free parts are identical.
    The square-free part of a number is the product of all prime factors that appear 
    an odd number of times in its prime factorization.
    """
    def get_square_free_part(n):
        res = 1
        d = 2
        temp = n
        while d * d <= temp:
            if temp % d == 0:
                count = 0
                while temp % d == 0:
                    count += 1
                    temp //= d
                if count % 2 == 1:
                    res *= d
            d += 1
        if temp > 1:
            res *= temp
        return res

    groups = {}
    for num in nums:
        sf = get_square_free_part(num)
        if sf not in groups:
            groups[sf] = 0
        groups[sf] += num

    return max(groups.values()) if groups else 0
