    n = max(nums)
    if len(nums) != n + 1:
        return False

    # Count occurrences of each number
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1

    # For the array to be a permutation of base[n]:
    # 1. Every number from 1 to n-1 must appear exactly once.
    # 2. The number n must appear exactly twice.
    for i in range(1, n):
        if counts.get(i, 0) != 1:
            return False

    if counts.get(n, 0) != 2:
        return False

    return True
