def punishmentNumber(n: int) -> int:
    def can_partition(s, target):
        # Base case: if the string is empty and target is 0, we found a valid partition
        if not s:
            return target == 0

        # Try all possible split points for the first substring
        for i in range(1, len(s) + 1):
            val = int(s[:i])
            # If the current substring value exceeds the target, further splits won't work
            if val > target:
                break
            if can_partition(s[i:], target - val):
                return True
        return False

    total_punishment = 0
    for i in range(1, n + 1):
        square_str = str(i * i)
        if can_partition(square_str, i):
            total_punishment += i * i

    return total_punishment
