import heapq

def minimumCost(source, target, original, changed, cost):
    # Initialize a 26x26 distance matrix with infinity
    # dist[i][j] will store the minimum cost to change character i to character j
    inf = float('inf')
    dist = [[inf] * 26 for _ in range(26)]

    # Distance to itself is 0
    for i in range(26):
        dist[i][i] = 0

    # Fill the matrix with given direct conversion costs
    for o, c, w in zip(original, changed, cost):
        u, v = ord(o) - ord('a'), ord(c) - ord('a')
        if w < dist[u][v]:
            dist[u][v] = w

    # Use Floyd-Warshall algorithm to find all-pairs shortest paths
    # Since there are only 26 characters, O(26^3) is very efficient
    for k in range(26):
        for i in range(26):
            for j in range(26):
                if dist[i][k] != inf and dist[k][j] != inf:
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    total_cost = 0
    # Calculate the total cost to transform source to target
    for s, t in zip(source, target):
        if s == t:
            continue
        u, v = ord(s) - ord('a'), ord(t) - ord('a')
        if dist[u][v] == inf:
            return -1
        total_cost += dist[u][v]

    return total_cost
