    n = len(s)
    positions = [i for i, ch in enumerate(s) if ch == '1']
    if len(positions) < k:
        return ""

    min_len = n + 1
    candidates = []

    for i in range(len(positions) - k + 1):
        start = positions[i]
        end = positions[i + k - 1]
        length = end - start + 1
        if length < min_len:
            min_len = length
            candidates = [s[start:end+1]]
        elif length == min_len:
            candidates.append(s[start:end+1])

    return min(candidates)
