import sys

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    H = int(input_data[1])
    W = int(input_data[2])

    tiles = []
    idx = 3
    for _ in range(N):
        tiles.append((int(input_data[idx]), int(input_data[idx+1])))
        idx += 2

    # Grid to keep track of covered cells
    grid = [[False for _ in range(W)] for _ in range(H)]

    # used_tiles keeps track of which tiles have been placed
    used_tiles = [False] * N

    def can_place(r, c, h, w):
        if r + h > H or c + w > W:
            return False
        for i in range(r, r + h):
            for j in range(c, c + w):
                if grid[i][j]:
                    return False
        return True

    def place(r, c, h, w, val):
        for i in range(r, r + h):
            for j in range(c, c + w):
                grid[i][j] = val

    def backtrack():
        # Find the first empty cell
        r, c = -1, -1
        for i in range(H):
            for j in range(W):
                if not grid[i][j]:
                    r, c = i, j
                    break
            if r != -1:
                break

        # If no empty cell is found, the grid is fully covered
        if r == -1:
            return True

        # Try placing each available tile
        for i in range(N):
            if not used_tiles[i]:
                # Try both orientations of the tile
                for h, w in [(tiles[i][0], tiles[i][1]), (tiles[i][1], tiles[i][0])]:
                    if can_place(r, c, h, w):
                        place(r, c, h, w, True)
                        used_tiles[i] = True
                        if backtrack():
                            return True
                        used_tiles[i] = False
                        place(r, c, h, w, False)
                    # If the tile is square, don't try the rotated version
                    if h == w:
                        break
        return False

    # Optimization: Check if total area of all tiles is less than grid area
    total_tile_area = sum(a * b for a, b in tiles)
    if total_tile_area < H * W:
        print("No")
        return

    if backtrack():
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
