import sys

def solve():
    # Read H, W, K from the first line of input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    K = int(input_data[2])
    S = input_data[3:]

    min_ops = float('inf')

    # Check horizontal sequences
    if W >= K:
        for i in range(H):
            row = S[i]
            # Use a sliding window to count 'x' and '.'
            current_x = 0
            current_dot = 0
            for j in range(W):
                # Add new element to window
                char = row[j]
                if char == 'x':
                    current_x += 1
                elif char == '.':
                    current_dot += 1

                # Remove element that falls out of window
                if j >= K:
                    out_char = row[j - K]
                    if out_char == 'x':
                        current_x -= 1
                    elif out_char == '.':
                        current_dot -= 1

                # If window size is K and no 'x' is present, it's a valid sequence
                if j >= K - 1:
                    if current_x == 0:
                        if current_dot < min_ops:
                            min_ops = current_dot

    # Check vertical sequences
    if H >= K:
        for j in range(W):
            # Extract column as a string/list
            current_x = 0
            current_dot = 0
            for i in range(H):
