import math

def canConnectAll(nums):
    """
    Determines if all indices in the array are connected based on the GCD > 1 rule.
    We use a Disjoint Set Union (DSU) to group indices that share common prime factors.
    """
    n = len(nums)
    if n == 1:
        return True

    # Parent array for DSU
    parent = list(range(n))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    # Map each prime factor to the first index encountered that has this factor
    prime_to_index = {}

    for i in range(n):
        val = nums[i]
        if val == 1:
            # 1 cannot be connected to any other number since gcd(1, x) = 1
            # Unless the array has only one element, it's impossible to connect all.
            return False

        # Factorize the number to find all prime factors
        d = 2
        temp = val
        while d * d <= temp:
            if temp % d == 0:
                if d in prime_to_index:
                    union(i, prime_to_index[d])
                else:
                    prime_to_index[d] = i
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            if temp in prime_to_index:
                union(i, prime_to_index[temp])
            else:
                prime_to_index[temp] = i

    # Check if all indices belong to the same connected component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False

    return True
