def solve(nums):
    import functools

    n = len(nums)
    MOD = 10**9 + 7

    # Precompute divisibility to avoid repeated modulo operations
    # adj[i] contains indices j such that nums[i] % nums[j] == 0 or vice versa
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                adj[i].append(j)
                adj[j].append(i)

    @functools.lru_cache(None)
    def dp(mask, last_idx):
        # Base case: all elements have been used
        if mask == (1 << n) - 1:
            return 1

        count = 0
        # Try all possible next elements in the permutation
        for next_idx in adj[last_idx]:
            # Check if the next element has not been used yet
            if not (mask & (1 << next_idx)):
                count += dp(mask | (1 << next_idx), next_idx)

        return count % MOD

    total_special_permutations = 0
    # Start the permutation with every possible element
    for i in range(n):
        total_special_permutations += dp(1 << i, i)

    return total_special_permutations % MOD
